{
  "code": "import pytest
import impl


def test_empty_rows():
    """Empty rows list returns empty string."""
    assert impl.write_csv([]) == ""


def test_single_field():
    """Single field in single row."""
    assert impl.write_csv([["hello"]]) == "hello\r\n"


def test_multiple_fields_no_quotes():
    """Multiple fields without quoting."""
    assert impl.write_csv([["a", "b", "c"]]) == "a,b,c\r\n"


def test_field_with_comma():
    """Field with comma should be quoted."""
    assert impl.write_csv([["Portland, OR"]]) == '"Portland, OR"\r\n'


def test_field_with_double_quote():
    """Field with double quote should be quoted and doubled."""
    assert impl.write_csv([['He said "hi"']]) == '"He said ""hi"""\r\n'


def test_field_single_double_quote():
    """Field that is a single double quote."""
    assert impl.write_csv([['"']]) == '"""""\r\n'


def test_field_with_crlf():
    """Field with CRLF should be quoted."""
    assert impl.write_csv([["line1\r\nline2"]]) == '"line1\r\nline2"\r\n'


def test_field_with_lone_lf():
    """Field with lone LF should be quoted and preserved."""
    assert impl.write_csv([["line1\nline2"]]) == '"line1\nline2"\r\n'


def test_field_with_lone_cr():
    """Field with lone CR should be quoted and preserved."""
    assert impl.write_csv([["line1\rline2"]]) == '"line1\rline2"\r\n'


def test_empty_field():
    """Empty field should be zero characters."""
    assert impl.write_csv([["", "b", ""]]) == ",b,\r\n"


def test_three_empty_fields():
    """Record with three empty fields."""
    assert impl.write_csv([["", "", ""]]) == ",,\r\n"


def test_empty_row():
    """Row with no fields should write just CRLF."""
    assert impl.write_csv([[]]) == "\r\n"


def test_multiple_rows():
    """Multiple rows with CRLF between them."""
    result = impl.write_csv([["a", "b"], ["c", "d"]])
    assert result == "a,b\r\nc,d\r\n"


def test_example_from_spec():
    """Example from the ticket specification."""
    result = impl.write_csv([["2", "Portland, OR", ""], []])
    assert result == '2,"Portland, OR",\r\n\r\n'


def test_spaces_not_quoted():
    """Spaces should not trigger quoting."""
    assert impl.write_csv([["  keep  my  spaces  "]]) == "  keep  my  spaces  \r\n"


def test_tab_not_quoted():
    """Tab should not trigger quoting."""
    assert impl.write_csv([["before\tafter"]]) == "before\tafter\r\n"


def test_type_error_int():
    """Integer field should raise TypeError with 'int' in message."""
    with pytest.raises(TypeError, match="int"):
        impl.write_csv([[123]])


def test_type_error_none():
    """None field should raise TypeError with 'NoneType' in message."""
    with pytest.raises(TypeError, match="NoneType"):
        impl.write_csv([[None]])


def test_type_error_bytes():
    """Bytes field should raise TypeError with 'bytes' in message."""
    with pytest.raises(TypeError, match="bytes"):
        impl.write_csv([[b"data"]])


def test_multiple_quotes_in_field():
    """Multiple double quotes should all be doubled."""
    assert impl.write_csv([['He said "hello" and "goodbye"']]) == '"He said ""hello"" and ""goodbye"""\r\n'"
}
